<script>(function(){var button=document.querySelector(".mobile-menu-toggle"),menu=document.getElementById("siteNavigation"),overlay=document.getElementById("siteMenuOverlay");if(!button||!menu||!overlay)return;function close(){menu.classList.remove("is-open");overlay.classList.remove("is-open");document.body.classList.remove("menu-open");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Menüyü aç");button.textContent="☰"}function open(){menu.classList.add("is-open");overlay.classList.add("is-open");document.body.classList.add("menu-open");button.setAttribute("aria-expanded","true");button.setAttribute("aria-label","Menüyü kapat");button.textContent="×"}button.addEventListener("click",function(){menu.classList.contains("is-open")?close():open()});overlay.addEventListener("click",close);menu.addEventListener("click",function(e){if(e.target.closest("a"))close()});document.addEventListener("keydown",function(e){if(e.key==="Escape")close()});window.addEventListener("resize",function(){if(window.innerWidth>560)close()})})();</script><script>(function(){var box=document.querySelector('.price-filter');if(!box)return;var min=document.getElementById('minPriceRange'),max=document.getElementById('maxPriceRange'),minOut=document.getElementById('minPriceValue'),maxOut=document.getElementById('maxPriceValue'),label=document.getElementById('priceRangeLabel'),fill=document.getElementById('priceRangeFill');var ceiling=Number(box.dataset.priceMax)||100000,step=Number(min.step)||100;var fmt=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0});function update(which){var a=Number(min.value),b=Number(max.value);if(which==='min'&&a>=b){a=Math.max(0,b-step);min.value=a}if(which==='max'&&b<=a){b=Math.min(ceiling,a+step);max.value=b}if(a>b){a=b;min.value=a}minOut.value=a>0?String(a):'';maxOut.value=b<ceiling?String(b):'';label.textContent=fmt.format(a)+' ₺ – '+(b>=ceiling?'ve üzeri':fmt.format(b)+' ₺');var left=(a/ceiling)*100,right=(b/ceiling)*100;fill.style.left=left+'%';fill.style.width=Math.max(0,right-left)+'%'}min.addEventListener('input',function(){update('min')});max.addEventListener('input',function(){update('max')});update('init')})();</script><script>(function(){var f=[document.getElementById('filterCountry'),document.getElementById('filterCity'),document.getElementById('filterDistrict'),document.getElementById('filterNeighborhood')];if(f.some(function(x){return !x}))return;var labels=['Ülke seçin','Şehir seçin','İlçe seçin','Semt / mahalle seçin'];function reset(i){for(var n=i;n<4;n++)f[n].innerHTML='<option value="0">'+labels[n]+'</option>'}async function load(i,parent){reset(i);if(!parent||parent==='0')return;var r=await fetch('<?= e(app_url('/locations/children')) ?>?parent_id='+encodeURIComponent(parent));if(!r.ok)return;(await r.json()).forEach(function(x){var o=document.createElement('option');o.value=x.id;o.textContent=x.name;f[i].appendChild(o)})}f[0].addEventListener('change',function(){load(1,this.value)});f[1].addEventListener('change',function(){load(2,this.value)});f[2].addEventListener('change',function(){load(3,this.value)})})();</script></body></html>